const pipeline = reactive<PipelineRun>({
  task: '',
  workspacePath: '',
  stageIndex: -1,
  state: 'idle',
  log: [],
  projectId: '',
  projectFile: '',
  pipelineLogFile: '',
  backendLogFile: '',
  runDir: '',
  globalManager: null
})

/** The workspace the window's pipeline run belongs to.
 *
 *  `pipeline.workspacePath` cannot answer this: onWorkspaceBrowse reassigns it
