onUnmounted(() => stopDeepLinks?.())
// Workspaces the Resource Manager's storage scan walks: the open one first, then the recents that
// still exist on disk.
const knownWorkspacePaths = computed<string[]>(() => {
  const paths = [currentWorkspace.value, ...recentWorkspaces.value.filter((w) => w.exists).map((w) => w.path)]
  return [...new Set(paths.filter(Boolean))]
})
/**
 * Show the pane-authorization rules, from the account window.
 *
 * They live in a different window, and the account view's "your rules could not
 * be verified" notice used to name them in prose with nothing to click — in a
 * window that does not contain them.
 */
function openPanePolicySettings(): void {
  settingsInitialTab.value = 'cross-device'
  showSettings.value = true
  void nextTick(() => {
    void settingsModalRef.value?.setSection('cross-device', 'general-p2p-policy')
  })
}
function openSettingsAccounts(): void {
  settingsInitialTab.value = 'accounts'
  showSettings.value = true
}
// Status-bar update indicator: shares the updater state machine with ControlPane.
// settings comes along for the check-failure threshold; whether a downloaded
// update will be applied on quit is read from the STATE (quitInstallArmed),
// not the setting — the handoff to the OS updater is one-way.
const {
  state: updateState, settings: updaterSettings,
  startDownload: startUpdateDownload, installUpdate,
} = useUpdater()
// Feed the announcements centre from this one instance — useUpdater is not a
// singleton, so calling it again there would add another IPC subscription.
announcements.setUpdateSource(updateState)

// ── Quota-exhaustion failover: this window's answers to the backend ─────────
// The backend runs the switch; these hooks are what it asks this window for:
// is each of my panes safe to stop (and on which session can it come back),
// restart the listed ones through the same resume path the rebuild button
// uses, and label accounts for the announcement. Nothing here types into a
// pane: a switched pane comes back parked at its prompt with the continue
// button lit, exactly like a restore.
async function quotaPaneReadiness(paneId: string, opts: { needsResume: boolean }): Promise<PaneReadiness> {
  const pane = panes.value.find((p) => p.id === paneId)
  if (!pane?.realized) return { ready: false, reason: 'refused' }
  const ref = paneRefs[paneId]
  const status = ref?.displayStatus as string | undefined
  // Parked on the user — a permission box or a question — is never "idle":
  // stopping the pane would drop what it is waiting to hear.
  if (status === 'awaiting') return { ready: false, reason: 'permission-pending' }
  const hold = messagingHoldKey(paneId)
  if (hold === 'gone') return { ready: false, reason: 'refused' }
  if (hold === 'composer' || (hold === 'typing' && (ref?.hasDraft as boolean | undefined))) {
    return { ready: false, reason: 'input-pending' }
  }
  if (hold === 'not-ready') {
    // Not running and not idle: a PTY still starting can be waited for; an
    // exited or errored one has nothing to switch.
    return status === 'starting' ? { ready: false, reason: 'busy' } : { ready: false, reason: 'refused' }
  }
  if (hold !== null) return { ready: false, reason: 'busy' }
  const sessionId = paneResumeSessionId(pane) || null
  if (opts.needsResume) {
    // "Ready" for a restart switch is a promise that the pane can be brought
    // back on its conversation, so it runs the SAME preflight the rebuild
    // will: a vendor that resumes by id, a pinned session the rebuild gate
    // accepts, and that session actually present on disk right now. A pane
    // that would fail the rebuild says so here, before any credential moves.
    const spec = agentSpecs.find((s) => s.agentKey === pane.agentKey)
    if (!spec?.resumeArgs) return { ready: false, reason: 'not-resumable' }
    if (!sessionId) return { ready: false, reason: 'no-session' }
    if (!paneCanRebuild(pane)) return { ready: false, reason: 'not-resumable' }
    const onDisk = await canResumeSession(pane.agentKey, pane.workspacePath, sessionId)
    if (onDisk !== true) return { ready: false, reason: onDisk === false ? 'no-session' : 'not-resumable' }
    // The probe took time; the pane may have picked up work meanwhile.
    if (messagingHoldKey(paneId) !== null) return { ready: false, reason: 'busy' }
  }
  return { ready: true, sessionId, resumable: !!sessionId }
}

async function quotaRestartPane(pane: PrepareEventPane, ev: QuotaCommitEvent): Promise<RestartOutcome> {
  let newPaneId: string | null = null
  // The loop lives on the pane entry the rebuild replaces. When it is to
  // resume after the switch, carry it onto the replacement and arm it there —
  // never on the old pane, which is still on the exhausted process.
  const old = panes.value.find((p) => p.id === pane.paneId)
  const carryLoop = old && loopResumesAfterFailover(old, ev)
    ? { skillId: old.loopSkillId ?? null, turnCount: old.loopTurnCount ?? 0, maxTurns: old.loopMaxTurns ?? 0 }
    : null
  const failure = await rebuildPaneViaResume(pane.paneId, {
    suppressBusyToast: true,
    offerContinue: true,
    preserveScrollback: true,
    quotaCommit: ev,
    quotaOriginalPaneId: pane.originalPaneId ?? pane.paneId,
    onReplaced: (id) => {
      newPaneId = id
      const revived = carryLoop ? panes.value.find((p) => p.id === id) : undefined
      if (!carryLoop || !revived) return
      revived.loopActive = true
      revived.loopSkillId = carryLoop.skillId
      revived.loopTurnCount = carryLoop.turnCount
      revived.loopMaxTurns = carryLoop.maxTurns
      bumpLoopGen(id)
      startLoopLimitWatcher(id)
      revived.resumeContinueAvailable = false
      loopFailoverResumeArmed.set(id, Date.now())
    },
  })
  if (failure) return { outcome: 'failed', reason: failure }
  const id = newPaneId ?? pane.paneId
  const revived = panes.value.find((p) => p.id === id)
  return {
    outcome: 'resumed',
    paneId: id,
    termId: (paneRefs[id]?.sessionId as string | undefined) ?? null,
    sessionId: revived ? paneResumeSessionId(revived) || null : null,
  }
}

async function quotaOpenNewConversation(pane: PrepareEventPane, ev: QuotaCommitEvent): Promise<RestartOutcome> {
  // A fresh conversation the user agreed to — NOT the old pane's task. It
  // keeps the CLI, model and effort so the account is used the same way, but
  // no role, no stage and no kickoff: nothing from the interrupted work is
  // typed into it, and the old pane stays where it was with its pipeline
  // affiliation intact.
  const old = panes.value.find((p) => p.id === pane.paneId)
  const id = await onManualSpawn({
    agentKey: pane.agentKey,
    roleKey: '',
    stageId: '',
    model: old?.model ?? '',
    effort: old?.effort ?? '',
    workspacePath: pane.workspacePath || old?.workspacePath || currentWorkspace.value,
  } as SpawnPayload, { transactionId: ev.transactionId, originalPaneId: pane.originalPaneId ?? pane.paneId })
  if (!id) return { outcome: 'failed', reason: 'spawn-failed' }
  return { outcome: 'new-conversation', paneId: id, termId: (paneRefs[id]?.sessionId as string | undefined) ?? null }
}

function verifiedHotSwitchedPanes(agentKey: string, proofs: HotSwitchedPane[] | undefined, targetSlotId: string | null | undefined): HotSwitchedPane[] | undefined {
  return proofs?.filter((proof) => targetSlotId !== undefined &&
    (proof.profileId ?? '__default__') === (targetSlotId ?? '__default__') && proof.termId &&
    (proof.profileId === null || typeof proof.profileId === 'string' && proof.profileId !== '') &&
    panes.value.some((pane) => pane.id === proof.paneId && pane.agentKey === agentKey) &&
    paneRefs[proof.paneId]?.sessionId === proof.termId)
}

quotaFailover.initQuotaFailover(backend, {
  ownsPane: (paneId) => panes.value.some((p) => p.id === paneId && p.realized),
  paneReadiness: quotaPaneReadiness,
  restartPane: quotaRestartPane,
  openNewConversation: quotaOpenNewConversation,
  confirmNewConversation: (tx) =>
    notifyRestore.confirm(
      i18n.global.t('announce.quota.confirm-new-conversation-body', {
        agent: agentSpecs.find((s) => s.agentKey === tx.agentKey)?.label ?? tx.agentKey,
        target: accountLabel(cliProfilesApi, tx.agentKey, tx.toSlotId === '__default__' ? null : tx.toSlotId, i18n.global.t),
      }),
      {
        title: i18n.global.t('announce.quota.confirm-new-conversation-title'),
        confirmText: i18n.global.t('announce.quota.confirm-new-conversation-confirm'),
        cancelText: i18n.global.t('announce.quota.confirm-new-conversation-cancel'),
      },
    ),
  confirmLiveIsCurrent: (agentKey, currentSlotId, targetSlotId) => {
    const agent = agentSpecs.find((s) => s.agentKey === agentKey)?.label ?? agentKey
    const label = (slotId: string): string =>
      accountLabel(cliProfilesApi, agentKey, slotId === '__default__' ? null : slotId, i18n.global.t)
    const current = label(currentSlotId)
    return notifyRestore.confirm(
      tLogin('cli-account.live-drift-confirm-body', { agent, current, target: label(targetSlotId) }),
      {
        title: tLogin('cli-account.live-drift-confirm-title'),
        confirmText: tLogin('cli-account.live-drift-confirm-confirm', { current }),
        cancelText: tLogin('cli-account.live-drift-confirm-cancel'),
      },
    )
  },
  paneTermId: (paneId) => (paneRefs[paneId]?.sessionId as string | undefined) ?? null,
  paneSessionId: (paneId) => {
    const pane = panes.value.find((p) => p.id === paneId)
    return pane ? paneResumeSessionId(pane) || null : null
  },
  agentLabel: (agentKey) => agentSpecs.find((s) => s.agentKey === agentKey)?.label ?? agentKey,
  slotLabel: (agentKey, slotId) =>
    accountLabel(cliProfilesApi, agentKey, slotId === '__default__' ? null : slotId, i18n.global.t),
  onSwitchCommitted: (ev: QuotaCommitEvent) => {
    for (const proof of verifiedHotSwitchedPanes(ev.agentKey, ev.hotSwitchedPanes, ev.toSlotId) ?? []) {
      panes.value.find((p) => p.id === proof.paneId)!.profileId = proof.profileId ?? '__default__'
    }
    // Hold the pipeline quota gate on the affected panes until the incident
    // is verified (or stops): the exhausted-account flag is cleared by the
    // cli_profiles.changed that accompanies the commit, and without this a
    // replacement pane's blank flag would read as "quota back".
    for (const listed of ev.panes) {
      const pane = panes.value.find((p) => p.id === listed.paneId)
      if (pane) {
        pane.quotaGateIncidentId = ev.incidentId
        // A hot swap keeps the pane, so its loop is armed here; a restart
        // armed its replacement pane already (quotaRestartPane).
        if (ev.switchMode === 'hot' && loopResumesAfterFailover(pane, ev)) {
          loopFailoverResumeArmed.set(pane.id, Date.now())
        }
        if (loopFailoverResumeArmed.has(pane.id)) pane.resumeContinueAvailable = false
        else if (pane.loopActive) pane.resumeContinueAvailable = true
      }
    }
  },
  onIncidentReady: (incident: FailoverIncident) => releaseQuotaGate(incident.id),
  onSwitchRefused: (code, message) => {
    notifyRestore.toast(
      plaintextTokenStoreMessage(message) ??
        i18n.global.t('announce.quota.switch-refused', { code, message: message || code }),
      { type: 'error' },
    )
  },
})

/** Lift the quota gate hold for every pane of an incident. The barrier that
 *  remains is usageLimitSeenAt: a stage still needs a turn that ENDED after
 *  the block was seen (completion.ts quotaTurnIsFresh). */
function releaseQuotaGate(incidentId: string): void {
  for (const pane of panes.value) {
    if (pane.quotaGateIncidentId === incidentId) pane.quotaGateIncidentId = null
  }
}
// A stopped incident does NOT release the hold: "switched, quota
// unconfirmed" or "the new account ran out too" is not a recovery. The hold
// lifts on evidence only — the incident reaching `ready`, or the user
// dismissing the pane's quota badge (dismissPaneUsageLimit).
// A run of failed background checks is not an update status of its own — it
// rides alongside whatever the status is. Surface it in the status bar only
// once it clears the user's threshold, and only if they asked to be told.
const showUpdateCheckFailure = computed(() => {
  if (!updaterSettings.value.notifyOnCheckFailure) return false
  const failure = updateState.value.lastCheckFailure
  return !!failure && failure.count >= updaterSettings.value.checkFailureThreshold
})
// Drive the whole update flow from the status-bar badge instead of only opening
// Settings: available → start the download; downloaded → confirm then restart to
// install; downloading/error → open the Updates tab for progress or details.
async function onUpdateBadgeClick(): Promise<void> {
  const status = updateState.value.status
  if (status === 'available') {
    await startUpdateDownload()
    return
  }
  if (status === 'downloaded') {
    const ok = await notifyRestore.confirm(
      i18n.global.t('updater.restart-confirm-body', { version: updateState.value.availableVersion ?? '' }),
      {
        title: i18n.global.t('updater.restart-confirm-title'),
        confirmText: i18n.global.t('updater.install'),
        cancelText: i18n.global.t('updater.later'),
      }
    )
    if (!ok) return
    await installUpdate()
    return
  }
  settingsInitialTab.value = 'updates'
  showSettings.value = true
}
// Native application menu actions routed from main (menu:action). Existing
// bridge listeners in this file never unsubscribe — App.vue lives for the
// window's lifetime, so follow suit.
async function onMenuAction(action: string): Promise<void> {
  if (action === 'open-settings') {
    showSettings.value = true
    return
  }
  if (action === 'open-account') {
    openAccountModal()
    return
  }
  if (action === 'show-whats-new') {
    showWhatsNewOnDemand()
    return
  }
  if (action === 'show-welcome-tour') {
    replayWelcomeTour()
    return
  }
  if (action === 'show-shortcuts') {
    // Same destination as Cmd+K Cmd+S: two entry points labelled "Keyboard
    // Shortcuts" must not show two different lists.
    openSettingsAt('keybindings')
    return
  }
  if (action === 'check-updates') {
    settingsInitialTab.value = 'updates'
    showSettings.value = true
    // Refresh the tab's status in the background; failures surface in the tab.
    void window.agentTeam?.updater?.check?.()
    return
  }
  if (action === 'open-workspace') {
    const picked = await window.agentTeam?.pickWorkspace?.()
    if (!picked) return
    // Same folder already open in another window → focus it instead of
    // duplicating (two windows on one folder means conflicting PTY/git ops).
    if (await window.agentTeam?.focusWorkspaceWindow?.(picked)) return
    void touchRecentWorkspace(picked) // bump to front of recents
    if (!currentWorkspace.value) {
      // Welcome is showing — open in place via Welcome's @select handler.
      onWorkspaceSelected(picked)
      return
    }
    await window.agentTeam?.openMainWindow?.({ workspace_path: picked })
    return
  }
  if (action.startsWith('open-recent:')) {
    const picked = action.slice('open-recent:'.length)
    if (!picked) return
    if (await window.agentTeam?.focusWorkspaceWindow?.(picked)) return
    void touchRecentWorkspace(picked) // bump to front of recents
    if (!currentWorkspace.value) {
      onWorkspaceSelected(picked)
      return
    }
    await window.agentTeam?.openMainWindow?.({ workspace_path: picked })
    return
  }
}
const showHistory = ref(false)

/** Open the history modal for the workspace whose heading was clicked.
 *
 *  It answers for that workspace without switching to it: the modal reads its
 *  own copy of that project's entries, and every write it can perform names
 *  historyViewWorkspace rather than currentWorkspace. Opening the workspace on
 *  screen is the ordinary path and touches none of it. */
async function onOpenWorkspaceHistory(workspacePath?: string): Promise<void> {
  const foreign =
    workspacePath && normWs(workspacePath) !== normWs(currentWorkspace.value) ? workspacePath : ''
  historyWorkspace.value = foreign
  showHistory.value = true
  // One path for both cases: opening is a refresh, so the foreign load runs
  // under the same busy flag the button uses instead of beside it.
  await onRefreshHistory()
}

// Closed from the button, from Esc, or by an action that leaves the modal —
// dropping the copy once here covers every one of them. Keeping it would show
// a stale snapshot on the next open, before its own load lands.
watch(showHistory, (open) => {
  if (!open) resetForeignHistory()
})
const historyModalRef = ref<{ closeTopLayer?: () => boolean } | null>(null)
const revivingHistoryPaneId = ref('')
const unavailableHistoryPaneIds = ref<Set<string>>(new Set())

// ── Titlebar & Status Bar ─────────────────────────────────────────────────────
// The titlebar and document.title name. An alias belongs here too: the window
// title is how a project is picked out of Mission Control, and it would be the
// one surface still showing the folder name.
const workspaceBaseName = computed(() => {
  if (!currentWorkspace.value) return 'Navide'
  return wsDisplayName(currentWorkspace.value) || 'Navide'
})

/** The workspace's path for the titlebar, home collapsed to ~. Empty until
 *  the home directory arrives, which only means it renders in full a moment
 *  later — never a bare path where a shortened one was expected. */
const workspaceDisplayPath = computed(() =>
  currentWorkspace.value ? collapseHomePath(currentWorkspace.value, homeDir.value) : ''
)

// Reflect the open workspace in the real window title (document.title) so each
// main window is distinguishable in macOS Mission Control / the Dock. Without
// this every main window shows the static index.html <title>. Follows the
// shared `<context> — <feature>` window naming (docs/en-US/plugin-development.md);
// the plugin windows set their own title the same way.
watch(
  workspaceBaseName,
  (name) => {
    document.title = currentWorkspace.value ? `${name} — Navide` : 'Navide'
  },
  { immediate: true },
)

interface StatusBarGit {
  branch: string
  ahead: number
  behind: number
  dirty: boolean
}
const statusBarGit = ref<StatusBarGit>({ branch: '', ahead: 0, behind: 0, dirty: false })

async function refreshStatusBarGit(): Promise<void> {
  if (!currentWorkspace.value || !workspaceSelected.value) return
  if (backend.status.value !== 'connected') return
  const resp = await sendQuiet<{
    branch: string; ahead: number; behind: number
    staged: unknown[]; unstaged: unknown[]
  }>('git.status', { workspace_path: currentWorkspace.value })
  if (resp) {
    statusBarGit.value = {
      branch: resp.branch || '',
      ahead: resp.ahead ?? 0,
      behind: resp.behind ?? 0,
      dirty: (resp.staged?.length ?? 0) + (resp.unstaged?.length ?? 0) > 0
    }
    return
  }
  // A cold-start git.status can time out even once the socket reports
  // connected, and sendQuiet does not retry. The old 5s poll papered over that
  // by simply asking again; with nothing scheduled the bar would sit blank
  // until the workspace changed or something on disk did. One bounded retry —
  // only while the bar has nothing to show, so a transient failure during
  // normal use never turns into a second poll.
  if (_gitRetryTimer === null && !statusBarGit.value.branch) {
    _gitRetryTimer = window.setTimeout(() => {
      _gitRetryTimer = null
      void refreshStatusBarGit()
    }, 3000)
  }
}

// Event-driven, not polled. A 5s interval here spawned three git subprocesses
// per tick per window (rev-parse, status --porcelain, rev-parse --git-dir) and
// ran whether or not anything had changed — measured at ~107 git processes a
// minute across three idle windows. The backend already broadcasts git.changed
// for every git write, every fs write, and every watched worktree/.git change,
// so the bar can just listen. Coalesced because one user action (a commit, a
// checkout) fans out into several file events.
let _windowVisible = true
let _gitStale = false
let _gitRefreshTimer: number | null = null
let _gitRetryTimer: number | null = null
function scheduleStatusBarGit(): void {
  // Hidden windows do no git work; they mark themselves stale and catch up on
  // the way back in. Main reports visibility over IPC rather than the Page
  // Visibility API: terminal panes need backgroundThrottling disabled, which
  // pins document.hidden to false.
  if (!_windowVisible) { _gitStale = true; return }
  if (_gitRefreshTimer !== null) return
  _gitRefreshTimer = window.setTimeout(() => {
    _gitRefreshTimer = null
    // Re-checked: the window can go away during the 300ms wait, and firing
    // then is the one case the visibility guard above would still let through.
    if (!_windowVisible) { _gitStale = true; return }
    void refreshStatusBarGit()
  }, 300)
}
const _offWindowVisibility = window.agentTeam?.onWindowVisibility?.((visible: boolean) => {
  _windowVisible = visible
  if (visible && _gitStale) { _gitStale = false; void refreshStatusBarGit() }
})
const _offGitChanged = backend.on('git.changed', (raw) => {
  const ws = (raw as { workspace_path?: string } | null)?.workspace_path
  if (!ws || ws !== currentWorkspace.value) return
  scheduleStatusBarGit()
})
onUnmounted(() => {
  _offWindowVisibility?.()
  _offGitChanged?.()
  if (_gitRefreshTimer !== null) { clearTimeout(_gitRefreshTimer); _gitRefreshTimer = null }
  if (_gitRetryTimer !== null) { clearTimeout(_gitRetryTimer); _gitRetryTimer = null }
})
// git.changed broadcasts sent while this window was disconnected are gone for
// good, and without a poll nothing would ever fetch them. Resync on reconnect.
watch(() => backend.status.value, (s) => {
  if (s === 'connected' && workspaceSelected.value) void refreshStatusBarGit()
})
watch(workspaceSelected, (v) => {
  if (v) void refreshStatusBarGit()
  else statusBarGit.value = { branch: '', ahead: 0, behind: 0, dirty: false }
}, { immediate: true })

// Switching between two workspaces this window holds never flips
// workspaceSelected, so the watch above does not fire and the bar kept showing
// the branch of the workspace being left. Wrong is worse than absent here: a
// branch name next to a project you just switched to reads as that project's
// branch. Cleared first, then refetched.
watch(currentWorkspace, () => {
  statusBarGit.value = { branch: '', ahead: 0, behind: 0, dirty: false }
  // The staleness belonged to the workspace being left; this refetch settles
  // the new one, so carrying the flag over only buys a duplicate request when
  // the window next comes to the front.
  _gitStale = false
  void refreshStatusBarGit()
})
