    <SettingsModal
      ref="settingsModalRef"
      v-if="showSettings"
      :backend="backend"
      :roles-api="rolesApi"
      :stages-api="stagesApi"
      :analyzer-api="analyzerApi"
      :pipelines-api="pipelinesApi"
      :cli-profiles-api="cliProfilesApi"
      :workspace-open="!!currentWorkspace"
